 const state={progress:new Map(),inline:new Map(),pendingNotice:null,cacheKey:null,answerPreviewed:false,scheduleDrafts:[],scheduleBatch:null,epoch:0,host:null,options:{},list:null,marks:null,detail:null,paperOnly:false,answerOnly:false,resultOnly:false,phase:null,registerId:null,reportRegisterId:null,validationSummary:null,editRegister:null,registerValidation:null,registerFilter:'ALL',tab:'schedule',busy:false,dirty:false,pending:null,session:'',urls:[]};
