   const groups=new Map();for(const a of rows){if(!groups.has(a.registerId))groups.set(a.registerId,[]);groups.get(a.registerId).push(a);}
   return [...groups].map(([id,entries])=>timetableHTML(entries,{id,name:entries[0].phaseName||'Imtihaan',classMode:'ALL',classLabel:entries.some(a=>a.sharedAllClasses===false)?'Your classes':'All classes',areas:[...new Map(entries.map(a=>[a.activityKey,{name:a.activityName,key:a.activityKey}])).values()]})).join('');
