   const heading=exams[0],staff=exams.some(a=>a.canTeach),learner=window.M4L_ACADEMY_WORKSPACE?.audience()==='LEARN',showResults=!learner&&exams.some(a=>a.canTeach&&(a.readyForAssessmentAt||a.resultsStatus==='RELEASED')),showMarks=exams.some(a=>a.releasedMark!=null),admin=exams.some(a=>a.canAdmin),addDate=state.options.view==='admin'&&!state.registerId&&!heading.phaseId&&exams.some(a=>a.canAdmin);
