 function showAnswerHelp(){
  const dialog=document.createElement('dialog');dialog.className='as-workspace as-paper-dialog';dialog.setAttribute('aria-labelledby','as-scan-help-title');
  dialog.innerHTML='<div class="as-toolbar"><h3 id="as-scan-help-title">Creating your answer PDF</h3><button type="button" class="as-button as-secondary academy-close" data-help-close title="Close">Close</button></div><p>Scan all your answer pages into one PDF. Place the pages flat in good light and keep the full page in view.</p><details open><summary>iPhone or iPad</summary><p>Open Files, tap More (…), then Scan Documents. Scan each page into the same document, finish, choose a location and save. You can also scan using Notes.</p><a href="https://support.apple.com/en-us/108963" target="_blank" rel="noopener noreferrer">Apple scanning instructions</a></details><details><summary>Android</summary><p>Open Files by Google and tap Scan. Scan the first page, use Add for the remaining pages, then tap Done. Find the PDF in Downloads → Scanned.</p><a href="https://support.google.com/files/answer/15598575?hl=en" target="_blank" rel="noopener noreferrer">Google scanning instructions</a></details><p>Return here and select your PDF. Preview it and check that every page is present, readable and correctly ordered. Then choose Submit answers and wait for the Answers received confirmation.</p>';
  dialog.querySelector('[data-help-close]').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());document.body.appendChild(dialog);dialog.showModal();
 }
 function showHelp(){
  let dialog=document.getElementById('as-help-dialog');
  if(!dialog){dialog=document.createElement('dialog');dialog.id='as-help-dialog';document.body.appendChild(dialog);}
  dialog.innerHTML=`<div class="as-workspace"><div class="as-toolbar"><h2>Assessment process</h2>${button('Close','close-help','',true)}</div>
   <p>Use the Imtihaan Register to open the assessment table or Edit reports. Back or Close returns to the register.</p>
   <ol class="as-help-flow">
    <li><strong>Release the schedule</strong><p>Choose the Programs or Courses and classes, add assessments, then Validate schedule and Release schedule from the register. Assignment deadlines are 13:00 on their due date in the Academy timezone.</p></li>
    <li><strong>Approve and publish papers</strong><p>Admin edits the assessment table and saves changes together with Save all. Select an examiner from the Program or Course teacher list. The examiner can attach a PDF before approval; Admin can replace it later, including after release, with confirmation. The uploader is recorded separately. Validate papers checks the current PDF, approval, details and released schedule. Publish papers releases the eligible approved papers; remaining papers can follow later.</p></li>
    <li><strong>Check submissions and enter marks</strong><p>Only the assigned examiner and authorised Admins can open paper PDFs, view submissions, confirm receipt or enter marks. Other teachers see details and status. Review each received answer PDF before confirming receipt. Enter marks first, then a moderator confirms the marks. A changed mark needs fresh moderation.</p></li>
    <li><strong>Validate marking and generate reports</strong><p>From the register, validate current marks, moderation and submission receipts. Only Global Admin can override missing marks or unconfirmed receipts, with a reason. Missing marks remain Pending. Generate and review reports from the moderated marks before releasing marks.</p></li>
    <li><strong>Release marks and reports</strong><p>Release marks for the whole Imtihaan from the register. Reports may be released with marks or later. Learners see only their own released results. Mark complete or Cancel with confirmation from the register.</p></li>
   </ol><p>Delete assessment removes an unused paper from the active schedule while retaining its audit record. Deletion is blocked once learner access or submissions begin. Replacing a released paper preserves existing submissions; Admin decides any follow-up case by case and may compose a learner notice.</p></div>`;
  dialog.querySelector('[data-as="close-help"]').onclick=()=>dialog.close();dialog.showModal();
 }
 async function open(options){reset();state.options=options;state.registerId=options.view==='admin'?options.registerId||null:null;state.host=document.getElementById(options.hostId);state.session=token();state.tab='schedule';if(!state.host)return;if(!state.session){state.host.textContent='Sign in to view assessments.';return;}
  const epoch=state.epoch,session=state.session;
  if(options.view==='learner')try{const digest=[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(session+JSON.stringify(options))))].map(n=>n.toString(16).padStart(2,'0')).join('');if(!active(epoch,session))return;const owner=[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(session)))].map(n=>n.toString(16).padStart(2,'0')).join('');if(!active(epoch,session))return;const prefix='m4l_assessment_10771_'+owner+'_';for(const key of Object.keys(sessionStorage))if(key.startsWith('m4l_assessment_')&&!key.startsWith(prefix))sessionStorage.removeItem(key);state.cacheKey=prefix+digest;const cached=JSON.parse(sessionStorage.getItem(state.cacheKey)||'null');if(cached&&Date.now()-cached.at<86400000){state.list=cached.list;await render();message('Refreshing assessments…');}}catch{}
  if(!active(epoch,session))return;if(!state.list)shell('<p>Opening assessments…</p>');
  try{await refresh(true);if(active(epoch,session))message('');}catch(e){if(!active(epoch,session))return;if([401,403].includes(e.status)){if(state.cacheKey)sessionStorage.removeItem(state.cacheKey);state.list=null;shell('<p>Sign in again or check your assessment access.</p>');}else message(state.list?'Could not refresh. Showing your last loaded assessments.':e.message,true);}
 }
